#!/bin/bash
# PreToolUse hook for Edit and Write: generated files change only by regenerating them.
#
# Paths are judged from the root of the checkout that holds the file, not from
# $CLAUDE_PROJECT_DIR, which stays at the starting root after Claude enters a worktree.
# Claude Code blocks a call on exit 2. settings.json sets onFailure to block, so a crash,
# another exit code or a timeout blocks too, but every denial and every failure to judge
# the path still ends here, in exit 2, so that Claude sees the reason on stderr.
deny() {
  echo "$1" >&2
  exit 2
}

for tool in jq realpath; do
  command -v "$tool" >/dev/null || deny "Edit denied: deny-generated-edits.sh needs $tool. Install it."
done

input=$(cat)
file_path=$(printf '%s' "$input" | jq -r '.tool_input.file_path | strings') ||
  deny "Edit denied: deny-generated-edits.sh could not parse its input."
cwd=$(printf '%s' "$input" | jq -r '.cwd | strings')

case "$file_path" in
  /*) ;;
  "") deny "Edit denied: the tool call has no usable file_path." ;;
  *)
    case "$cwd" in
      /*) file_path=$cwd/$file_path ;;
      *) deny "Edit denied: $file_path is relative and the hook input has no absolute cwd." ;;
    esac
    ;;
esac

# Resolve symlinks and .. one segment at a time, because the end of the path may not exist yet.
real_path=
IFS=/
set -f
for segment in $file_path; do
  case "$segment" in
    "" | .) ;;
    ..) real_path=${real_path%/*} ;;
    *)
      real_path=$real_path/$segment
      if [ -e "$real_path" ]; then
        real_path=$(realpath "$real_path") || deny "Edit denied: could not resolve $file_path."
      fi
      ;;
  esac
done
unset IFS
set +f

# A checkout's root holds .git, a directory in the main checkout and a file in a git worktree.
root=${real_path%/*}
until [ -z "$root" ] || [ -e "$root/.git" ]; do
  root=${root%/*}
done
[ -n "$root" ] || exit 0 # Outside any checkout.
relative_path=${real_path#"$root"/}

# Claude Code's default worktree location counts as a root even before git metadata exists.
case "$relative_path" in
  .claude/worktrees/*/*) relative_path=${relative_path#.claude/worktrees/*/} ;;
esac

# The default macOS filesystem ignores case, so BUILD/ and build/ are the same directory.
shopt -s nocasematch
case "$relative_path" in
  .godot/* | build/* | *.import)
    deny "$relative_path is generated by Godot. Change its source or re-import instead."
    ;;
  art/models/*)
    deny "$relative_path is generated. Change its script in art/scripts/ and rerun it in Blender."
    ;;
esac
